import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import ApiService from '../../Services/ApiService';
import { toast } from 'react-toastify';

export default function SellerReels() {
    const navigate = useNavigate();
    const [reels, setReels] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        // Initialize Remix Icons if available
        if (window.RemixIcon) {
            window.RemixIcon.init();
        }
        
        loadSellerReels();
    }, []);

    const loadSellerReels = async () => {
        try {
            setLoading(true);
            
            // Get seller reels from API
            // Note: In a real app, you would get the vendor ID from auth context or props
            const vendorId = 1; // Placeholder - in real app this would come from auth
            const response = await ApiService.getSellerReels(vendorId);
            
            if (response.success) {
                // Group reels by product and calculate counts
                const productMap = {};
                response.data.forEach(reel => {
                    // Get product name from the first product in the reel's product list
                    const productName = reel.products && reel.products.length > 0 
                        ? reel.products[0].name 
                        : 'Unknown Product';
                    
                    if (!productMap[productName]) {
                        productMap[productName] = {
                            product: productName,
                            reelCount: 0,
                            reels: [],
                            // Take properties from the first reel for display
                            title: reel.title,
                            category: reel.category_name || 'N/A',
                            status: reel.status,
                            views: 0,
                            likes: 0,
                            date: reel.created_at ? new Date(reel.created_at).toISOString().split('T')[0] : 'N/A'
                        };
                    }
                    productMap[productName].reelCount += 1;
                    productMap[productName].reels.push(reel);
                    // Accumulate views and likes
                    productMap[productName].views += reel.views || 0;
                    productMap[productName].likes += reel.likes || 0;
                });
                
                // Convert to array format for display
                const groupedReels = Object.values(productMap);
                setReels(groupedReels);
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading seller reels:', error);
            toast.error('Failed to load reels: ' + error.message);
            setLoading(false);
            
            // Fallback to sample data in case of error
            setTimeout(() => {
                const sampleReels = [
                    {
                        product: 'Summer Dress',
                        reelCount: 2,
                        title: 'New Summer Collection',
                        category: 'Fashion',
                        status: 'approved',
                        views: 2000,
                        likes: 440,
                        date: '2023-06-22',
                        reels: [
                            {
                                id: 1,
                                title: 'New Summer Collection',
                                products: [{name: 'Summer Dress'}],
                                category_name: 'Fashion',
                                status: 'approved',
                                views: 1250,
                                likes: 342,
                                created_at: '2023-06-15T10:30:00Z'
                            },
                            {
                                id: 4,
                                title: 'Summer Accessories',
                                products: [{name: 'Summer Dress'}],
                                category_name: 'Fashion',
                                status: 'approved',
                                views: 750,
                                likes: 98,
                                created_at: '2023-06-22T11:30:00Z'
                            }
                        ]
                    },
                    {
                        product: 'Winter Coat',
                        reelCount: 1,
                        title: 'Winter Sale Announcement',
                        category: 'Seasonal',
                        status: 'pending',
                        views: 0,
                        likes: 0,
                        date: '2023-06-18',
                        reels: [
                            {
                                id: 2,
                                title: 'Winter Sale Announcement',
                                products: [{name: 'Winter Coat'}],
                                category_name: 'Seasonal',
                                status: 'pending',
                                views: 0,
                                likes: 0,
                                created_at: '2023-06-18T09:45:00Z'
                            }
                        ]
                    },
                    {
                        product: 'Spring Shoes',
                        reelCount: 1,
                        title: 'New Arrival: Spring Shoes',
                        category: 'Footwear',
                        status: 'approved',
                        views: 2100,
                        likes: 567,
                        date: '2023-06-10',
                        reels: [
                            {
                                id: 3,
                                title: 'New Arrival: Spring Shoes',
                                products: [{name: 'Spring Shoes'}],
                                category_name: 'Footwear',
                                status: 'approved',
                                views: 2100,
                                likes: 567,
                                created_at: '2023-06-10T16:20:00Z'
                            }
                        ]
                    }
                ];
                setReels(sampleReels);
            }, 500);
        }
    };

    const handleViewReelVideo = async (productId) => {
        // Navigate to the view page for this product
        navigate(`/studio/seller/reels/${encodeURIComponent(productId)}`);
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 'approved':
                return <span className="badge bg-success">Approved</span>;
            case 'pending':
                return <span className="badge bg-warning">Pending</span>;
            case 'rejected':
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">My Reels</h4>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="card-title mb-0">Reels Management</h5>
                        <Link to="/studio/seller/upload" className="btn btn-success">
                            <i className="ri-add-line me-1"></i> Upload Reel
                        </Link>
                    </div>
                    <div className="card-body">
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                            </div>
                        ) : reels.length === 0 ? (
                            <div className="text-center py-5">
                                <h5>No reels found</h5>
                                <p className="text-muted">Upload your first reel to get started.</p>
                                <Link to="/studio/seller/upload" className="btn btn-success">
                                    <i className="ri-upload-line me-1"></i> Upload Reel
                                </Link>
                            </div>
                        ) : (
                            <div className="table-responsive">
                                <table className="table table-hover align-middle mb-0">
                                    <thead>
                                        <tr>
                                            <th>Product Name</th>
                                            <th>Reel Count</th>
                                            <th>Title</th>
                                            <th>Category</th>
                                            <th>Status</th>
                                            <th>Views</th>
                                            <th>Likes</th>
                                            <th>Date</th>
                                            <th>Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {reels.map((productGroup) => (
                                            <tr key={productGroup.product}>
                                                <td>{productGroup.product}</td>
                                                <td>{productGroup.reelCount}</td>
                                                <td>{productGroup.title}{productGroup.reelCount > 1 ? ` (+${productGroup.reelCount - 1} more)` : ''}</td>
                                                <td>{productGroup.category || 'N/A'}</td>
                                                <td>{getStatusBadge(productGroup.status)}</td>
                                                <td>{productGroup.views}</td>
                                                <td>{productGroup.likes}</td>
                                                <td>{productGroup.date}</td>
                                                <td>
                                                    <button 
                                                        className="btn btn-sm btn-info"
                                                        onClick={() => handleViewReelVideo(productGroup.product)}
                                                        title="View Reels"
                                                    >
                                                        <i className="ri-eye-line"></i> View
                                                    </button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
